// ============================================================================// VLR Wavefront vs VLR Comparison Test// // This test compares the rendering results of VLR_WF (Wavefront Path Tracing)// with VLR (original Path Tracing) to ensure they produce consistent results.// // Scene specifications:// - Simple Cornell Box with multiple materials// - Various camera settings// - Different ray tracing parameters// // Author: VLR Development Team// Created: 2026-03-07// Environment: CUDA 13.1, OptiX 8.0.0, VS2022// ============================================================================#include <vlr/vlr.h>#include <cuda_runtime.h>#include <cstdio>#include <cstdlib>#include <cstring>#include <cmath>#include <vector>#define STB_IMAGE_WRITE_IMPLEMENTATION#include "stb_image_write.h"// ============================================================================// Helper: Save PNG Image// ============================================================================static void savePNG(const char* filename, uint32_t width, uint32_t height,                    const float* rgb, uint32_t numSamples, float exposure) {    std::vector<unsigned char> pixels(width * height * 3);    float invSamples = (numSamples > 0) ? (1.0f / (float)numSamples) : 1.0f;    for (uint32_t y = 0; y < height; ++y) {        uint32_t srcY = height - 1 - y;        for (uint32_t x = 0; x < width; ++x) {            uint32_t srcIdx = (srcY * width + x) * 3;            uint32_t dstIdx = (y * width + x) * 3;            float r = rgb[srcIdx + 0] * invSamples * exposure;            float g = rgb[srcIdx + 1] * invSamples * exposure;            float b = rgb[srcIdx + 2] * invSamples * exposure;            r = r < 0 ? 0 : (r > 1 ? 1 : r);            g = g < 0 ? 0 : (g > 1 ? 1 : g);            b = b < 0 ? 0 : (b > 1 ? 1 : b);            r = powf(r, 1.0f / 2.2f);            g = powf(g, 1.0f / 2.2f);            b = powf(b, 1.0f / 2.2f);            pixels[dstIdx + 0] = (unsigned char)(r * 255.99f);            pixels[dstIdx + 1] = (unsigned char)(g * 255.99f);            pixels[dstIdx + 2] = (unsigned char)(b * 255.99f);        }    }    if (stbi_write_png(filename, width, height, 3, pixels.data(), width * 3)) {        printf("[Done] Image saved: %s (%u x %u)\n", filename, width, height);    } else {        fprintf(stderr, "[Error] Failed to save PNG: %s\n", filename);    }}// ============================================================================// Cornell Box Geometry// ============================================================================// L=-1.5, R=1.5, B=0, T=3, N=-1.5, F=1.5// All normals point inward (into box interior)// Floor (y=B=0): normal +Ystatic const float kFloorVertices[] = {    -1.5f, 0.0f, 1.5f,  -1.5f, 0.0f, -1.5f,  1.5f, 0.0f, -1.5f,  1.5f, 0.0f, 1.5f};static const uint32_t kFloorIndices[] = { 0, 1, 2,  0, 2, 3 };// Ceiling (y=T=3): normal -Ystatic const float kCeilingVertices[] = {    -1.5f, 3.0f, -1.5f,  -1.5f, 3.0f, 1.5f,  1.5f, 3.0f, 1.5f,  1.5f, 3.0f, -1.5f};static const uint32_t kCeilingIndices[] = { 0, 1, 2,  0, 2, 3 };// Back wall (z=N=-1.5): normal +Zstatic const float kBackWallVertices[] = {    -1.5f, 0.0f, -1.5f,  1.5f, 0.0f, -1.5f,  1.5f, 3.0f, -1.5f,  -1.5f, 3.0f, -1.5f};static const uint32_t kBackWallIndices[] = { 0, 1, 2,  0, 2, 3 };// Left wall (x=L=-1.5): normal +Xstatic const float kLeftWallVertices[] = {    -1.5f, 0.0f, 1.5f,  -1.5f, 0.0f, -1.5f,  -1.5f, 3.0f, -1.5f,  -1.5f, 3.0f, 1.5f};static const uint32_t kLeftWallIndices[] = { 0, 1, 2,  0, 2, 3 };// Right wall (x=R=1.5): normal -Xstatic const float kRightWallVertices[] = {    1.5f, 0.0f, -1.5f,  1.5f, 0.0f, 1.5f,  1.5f, 3.0f, 1.5f,  1.5f, 3.0f, -1.5f};static const uint32_t kRightWallIndices[] = { 0, 1, 2,  0, 2, 3 };// Area light: y=2.9, size 1.0×1.0 (from -0.5 to 0.5 in x and z)static const float kLightVertices[] = {    -0.5f, 2.9f, -0.5f,  0.5f, 2.9f, -0.5f,  0.5f, 2.9f, 0.5f,  -0.5f, 2.9f, 0.5f};static const uint32_t kLightIndices[] = { 0, 1, 2,  0, 2, 3 };// ============================================================================// Test Case Structure// ============================================================================struct TestCase {    const char* name;    uint32_t width;    uint32_t height;    uint32_t numSamples;    float cameraPosition[3];    float cameraDirection[3];    float cameraFovY;    float cameraLensRadius;    float cameraFocusDistance;    VLRRenderer renderer;};// ============================================================================// Main// ============================================================================int main(int argc, char** argv) {    printf("=== VLR_WF vs VLR Comparison Test START ===\n");    fflush(stdout);    // Test cases    TestCase testCases[] = {        {            "cornell_box_basic",            512, 512, 128,            { 0.0f, 1.5f, 6.0f },            { 0.0f, 0.0f, -1.0f },            40.0f,            0.0f,            1.0f,            VLRRenderer_WavefrontPathTracing        },        {            "cornell_box_dof",            512, 512, 256,            { 0.0f, 1.5f, 6.0f },            { 0.0f, 0.0f, -1.0f },            40.0f,            0.02f,            5.0f,            VLRRenderer_WavefrontPathTracing        },        {            "cornell_box_wide_fov",            512, 512, 128,            { 0.0f, 1.5f, 3.0f },            { 0.0f, 0.0f, -1.0f },            60.0f,            0.0f,            1.0f,            VLRRenderer_WavefrontPathTracing        },        // Add more test cases as needed    };    const int numTestCases = sizeof(testCases) / sizeof(testCases[0]);    VLRContext context = nullptr;    VLRScene scene = nullptr;    VLRResult res = VLRResult_Success;    VLRCameraParams camera = {};    // Create context and scene    res = vlrCreateContext(nullptr, 0, &context);    if (res != VLRResult_Success || !context) {        fprintf(stderr, "[Error] Failed to create Context: %d\n", res);        return 1;    }    res = vlrCreateScene(context, &scene);    if (res != VLRResult_Success || !scene) {        fprintf(stderr, "[Error] Failed to create Scene: %d\n", res);        vlrDestroyContext(context);        return 1;    }    // ========================================================================    // Materials (sRGB to linear)    // ========================================================================    float whiteColor[] = { 0.522f, 0.522f, 0.522f };    float redColor[] = { 0.522f, 0.0508f, 0.0508f };    float blueColor[] = { 0.0508f, 0.0508f, 0.522f };    float blackColor[] = { 0.0508f, 0.0508f, 0.0508f };    VLRMaterial matWhite = nullptr;    res = vlrCreateMaterial(scene, 0 /* Matte */, whiteColor, nullptr, &matWhite);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] White material\n"); goto cleanup; }    VLRMaterial matRed = nullptr;    res = vlrCreateMaterial(scene, 0 /* Matte */, redColor, nullptr, &matRed);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Red material\n"); goto cleanup; }    VLRMaterial matBlue = nullptr;    res = vlrCreateMaterial(scene, 0 /* Matte */, blueColor, nullptr, &matBlue);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Blue material\n"); goto cleanup; }    VLRMaterial matFloor = nullptr;    res = vlrCreateMaterialCheckerboard(scene, blackColor, whiteColor, 5, &matFloor);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Floor material\n"); goto cleanup; }    VLRMaterial matLight = nullptr;    float lightEmission[] = { 30.0f, 30.0f, 30.0f };    res = vlrCreateMaterial(scene, 0 /* Matte */, whiteColor, lightEmission, &matLight);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Light material\n"); goto cleanup; }    // ========================================================================    // Geometry    // ========================================================================    VLRTriangleMesh meshFloor = nullptr;    res = vlrCreateTriangleMesh(scene, kFloorVertices, 4, kFloorIndices, 2, matFloor, &meshFloor);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Floor mesh\n"); goto cleanup; }    VLRTriangleMesh meshCeiling = nullptr;    res = vlrCreateTriangleMesh(scene, kCeilingVertices, 4, kCeilingIndices, 2, matWhite, &meshCeiling);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Ceiling mesh\n"); goto cleanup; }    VLRTriangleMesh meshBackWall = nullptr;    res = vlrCreateTriangleMesh(scene, kBackWallVertices, 4, kBackWallIndices, 2, matWhite, &meshBackWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Back wall mesh\n"); goto cleanup; }    VLRTriangleMesh meshLeftWall = nullptr;    res = vlrCreateTriangleMesh(scene, kLeftWallVertices, 4, kLeftWallIndices, 2, matRed, &meshLeftWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Left wall mesh\n"); goto cleanup; }    VLRTriangleMesh meshRightWall = nullptr;    res = vlrCreateTriangleMesh(scene, kRightWallVertices, 4, kRightWallIndices, 2, matBlue, &meshRightWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Right wall mesh\n"); goto cleanup; }    VLRTriangleMesh meshLight = nullptr;    res = vlrCreateTriangleMesh(scene, kLightVertices, 4, kLightIndices, 2, matLight, &meshLight);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Light mesh\n"); goto cleanup; }    // ========================================================================    // Instances    // ========================================================================    float origin[] = { 0, 0, 0 };    float scale[] = { 1, 1, 1 };    float axis[] = { 0, 1, 0 };    VLRInstance instFloor = nullptr;    res = vlrCreateInstance(scene, meshFloor, origin, scale, axis, 0.0f, &instFloor);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Floor instance\n"); goto cleanup; }    VLRInstance instCeiling = nullptr;    res = vlrCreateInstance(scene, meshCeiling, origin, scale, axis, 0.0f, &instCeiling);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Ceiling instance\n"); goto cleanup; }    VLRInstance instBackWall = nullptr;    res = vlrCreateInstance(scene, meshBackWall, origin, scale, axis, 0.0f, &instBackWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Back wall instance\n"); goto cleanup; }    VLRInstance instLeftWall = nullptr;    res = vlrCreateInstance(scene, meshLeftWall, origin, scale, axis, 0.0f, &instLeftWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Left wall instance\n"); goto cleanup; }    VLRInstance instRightWall = nullptr;    res = vlrCreateInstance(scene, meshRightWall, origin, scale, axis, 0.0f, &instRightWall);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Right wall instance\n"); goto cleanup; }    VLRInstance instLight = nullptr;    res = vlrCreateInstance(scene, meshLight, origin, scale, axis, 0.0f, &instLight);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Light instance\n"); goto cleanup; }    res = vlrAddAreaLight(scene, instLight);    if (res != VLRResult_Success) { fprintf(stderr, "[Error] Add area light\n"); goto cleanup; }    // ========================================================================    // Run all test cases    // ========================================================================    for (int i = 0; i < numTestCases; ++i) {        const TestCase& testCase = testCases[i];        printf("\n=== Running test: %s ===\n", testCase.name);        printf("Resolution: %u x %u, Samples: %u\n", testCase.width, testCase.height, testCase.numSamples);        printf("Camera: pos=(%f, %f, %f), dir=(%f, %f, %f), fovY=%f, lensRadius=%f, focusDistance=%f\n",               testCase.cameraPosition[0], testCase.cameraPosition[1], testCase.cameraPosition[2],               testCase.cameraDirection[0], testCase.cameraDirection[1], testCase.cameraDirection[2],               testCase.cameraFovY, testCase.cameraLensRadius, testCase.cameraFocusDistance);        fflush(stdout);        // Set camera parameters        camera.position[0] = testCase.cameraPosition[0];        camera.position[1] = testCase.cameraPosition[1];        camera.position[2] = testCase.cameraPosition[2];        camera.direction[0] = testCase.cameraDirection[0];        camera.direction[1] = testCase.cameraDirection[1];        camera.direction[2] = testCase.cameraDirection[2];        camera.up[0] = 0.0f;        camera.up[1] = 1.0f;        camera.up[2] = 0.0f;        camera.fovY = testCase.cameraFovY * M_PI / 180.0f;        camera.aspect = (float)testCase.width / (float)testCase.height;        camera.lensRadius = testCase.cameraLensRadius;        camera.focusDistance = testCase.cameraFocusDistance;        camera.focalLength = 0.0f;        camera.cameraType = 0;        res = vlrSetCamera(scene, &camera);        if (res != VLRResult_Success) { fprintf(stderr, "[Error] Set camera\n"); goto cleanup; }        // Render        size_t bufferSize = testCase.width * testCase.height * sizeof(float) * 3;        float* outputBuffer = (float*)malloc(bufferSize);        if (!outputBuffer) {            fprintf(stderr, "[Error] Allocate output buffer\n");            goto cleanup;        }        res = vlrRender(context, scene, testCase.width, testCase.height, testCase.numSamples, testCase.renderer);        if (res != VLRResult_Success) {            fprintf(stderr, "[Error] Render failed: %d\n", res);            free(outputBuffer);            goto cleanup;        }        void* deviceBuffer = vlrGetOutputBuffer(context);        if (!deviceBuffer) {            fprintf(stderr, "[Error] Get output buffer\n");            free(outputBuffer);            goto cleanup;        }        cudaError_t cudaErr = cudaMemcpy(outputBuffer, deviceBuffer, bufferSize, cudaMemcpyDeviceToHost);        if (cudaErr != cudaSuccess) {            fprintf(stderr, "[Error] cudaMemcpy: %s\n", cudaGetErrorString(cudaErr));            free(outputBuffer);            goto cleanup;        }        // Save image        char filename[256];        sprintf(filename, "bin/%s.png", testCase.name);        savePNG(filename, testCase.width, testCase.height, outputBuffer, testCase.numSamples, 1.0f);        free(outputBuffer);    }    printf("\n=== All tests completed ===\n");cleanup:    vlrDestroyScene(scene);    vlrDestroyContext(context);    return (res == VLRResult_Success) ? 0 : 1;}